// pathbinding.js - 设置页入口 + 安装路径绑定面
//
// 设置页的四类关注点已按契约面拆开，本文件只剩两件：
//   1. 路径绑定面：GROUPS 数据表、自动扫描 / 手动编辑 / 浏览选择 / 实时校验，弹窗样式
//      与「设置 - 使用说明」一致；`window.pathbinding` 这个对外名字也由本文件挂载。
//   2. 入口装配：设置页按钮、系统信息折叠，以及按固定顺序拉起各面的 init。
//
// 加载顺序（两个清单都必须列全且同序）：
//   pathbinding-appearance.js  外观偏好的镜像与真源口径、重放登记（最先，各面只读它）
//   pathbinding-background.js  背景图（铺底 / 列表 / 视角雾化 / 预设背景 / 壁纸层模糊）
//   pathbinding-material.js    窗口材质（卡片 + 总开关 + 主进程广播）
//   pathbinding-wallpaper.js   实拍壁纸轮换（wp-*）
//   pathbinding.js             本文件：路径绑定面 + 入口装配（必须最后）
// 本文件必须最后：它装配各面，提前执行会让 `init` 在面板模块还没求值时就跑。
// GROUPS 的键集仍由本文件解析（数据对拍按本文件取），背景图列表的两句失败文案也钉在
// 本文件（Rust 侧源码形状断言按本文件字节判）。
//
// F4a2-L09：抖音图标常量必须留在 IIFE 内 —— 此前它落在文件顶层全局词法作用域，
// 任何其他脚本重名声明会让两份脚本一起 SyntaxError；收进后只属本模块作用域。
// 落 src/assets/ico/ 的彻底方案涉及资源移动与 tauri.conf bundle 清单同步（§2），
// 跨面另行派单，本文件不擅自搬资源。
(function () {
  'use strict';

  // 折叠头的键盘等价路径（A3-M03）：`ds.accordion.enhance` 只补 ARIA，不加 tabindex/keydown，
  // 所以 div 头当折叠开关时键盘走不到。本文件与 `pathbinding-background.js`、`cleanup.js`
  // 各留一份：ds.js 在首屏 12 脚本内而首屏预算已裁定不再上调（现算余量 48 B），
  // 不值得为只有按需页使用的能力挤首屏字节。三处接线由 check-a11y 的键盘接线判据钉住。
  function bindCollapseKeys(el) {
    if (!el || el.matches('button,a,input') || el.hasAttribute('tabindex')) return;
    el.setAttribute('tabindex', '0');
    if (!el.getAttribute('role')) el.setAttribute('role', 'button');
    el.addEventListener('keydown', (e) => {
      if ((e.key === 'Enter' || e.key === ' ') && e.target === el) {
        e.preventDefault();
        el.click();
      }
    });
  }

  // 抖音官方图标（内置 base64，避免依赖文件系统/asar 路径，任何环境 100% 可用）
  const DOUYIN_ICON = 'data:image/x-icon;base64,';

  // 分组定义：每组 = 软件名 + 图标候选 exe + 所属路径项（key/label/placeholder）
  // fixedIconPath：exe 提取的图标不正确时，直接使用指定的图标文件（例：抖音）
  const GROUPS = [
    {
      id: 'qq', name: 'QQ', exeCandidates: ['QQ.exe', 'QQScLauncher.exe'],
      iconFallback: '<svg viewBox="0 0 24 24" fill="currentColor"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-1 17.93c-3.95-.49-7-3.85-7-7.93 0-.62.08-1.21.21-1.79L9 15v1c0 1.1.9 2 2 2v1.93zm6.9-2.54c-.26-.81-1-1.39-1.9-1.39h-1v-3c0-.55-.45-1-1-1H8v-2h2c.55 0 1-.45 1-1V7h2c1.1 0 2-.9 2-2v-.41c2.93 1.19 5 4.06 5 7.41 0 2.08-.8 3.97-2.1 5.39z"/></svg>',
      items: [
        { key: 'qqInstallPath', label: '安装路径', placeholder: '如: C:\\Program Files\\Tencent\\QQNT' },
        { key: 'qqFileDir', label: '文件目录', placeholder: '如: C:\\Users\\xxx\\Documents\\Tencent Files' },
        { key: 'qqCacheDir', label: '缓存目录', placeholder: '自动发现后保存，或手动填写缓存目录' }
      ]
    },
    {
      id: 'wechat', name: '微信', exeCandidates: ['WeChat.exe', 'Weixin.exe', 'WeChatApp.exe'],
      iconFallback: '<svg viewBox="0 0 24 24" fill="currentColor"><path d="M8.691 2.188C3.891 2.188 0 5.476 0 9.53c0 2.212 1.17 4.203 3.002 5.55a.59.59 0 0 1 .213.665l-.39 1.48c-.019.07-.048.141-.048.213 0 .163.13.295.29.295a.326.326 0 0 0 .167-.054l1.903-1.114a.864.864 0 0 1 .717-.098 10.16 10.16 0 0 0 2.837.403c.276 0 .543-.027.811-.05-.857-2.578.157-4.972 1.932-6.446 1.703-1.415 3.882-1.98 5.853-1.98H20.5V9.53c0-4.054-3.891-7.342-8.691-7.342zM5.785 5.542A1.093 1.093 0 1 1 5.79 7.726a1.093 1.093 0 0 1-.005-2.184zm8.257 0a1.093 1.093 0 1 1 .005 2.184 1.093 1.093 0 0 1-.005-2.184z"/></svg>',
      items: [
        { key: 'wechatInstallPath', label: '安装路径', placeholder: '如: C:\\Program Files\\Tencent\\WeChat' },
        { key: 'wechatFileDir', label: '文件目录', placeholder: '如: C:\\Users\\xxx\\Documents\\xwechat_files' },
        { key: 'wechatCacheDir', label: '缓存目录', placeholder: '自动发现后保存，或手动填写 temp / Cache 目录' }
      ]
    },
    {
      id: 'douyin', name: '抖音', exeCandidates: ['Douyin.exe', 'douyin.exe'],
      // 抖音安装目录中的 exe 图标不正确，直接使用内置 base64 官方图标（任何环境 100% 可用，不依赖文件系统）
      iconDataUrl: DOUYIN_ICON,
      iconFallback: '<svg viewBox="0 0 24 24" fill="currentColor"><path d="M16.6 5.82A4.278 4.278 0 0 1 15.54 3h-3.09v12.4a2.592 2.592 0 0 1-2.59 2.5c-1.42 0-2.6-1.16-2.6-2.6 0-1.72 1.66-3.01 3.37-2.48V9.66c-3.45-.46-6.47 2.22-6.47 5.64 0 3.33 2.76 5.7 5.69 5.7 3.14 0 5.69-2.55 5.69-5.7V9.01a7.35 7.35 0 0 0 4.3 1.38V7.3a4.3 4.3 0 0 1-4.3-1.48z"/></svg>',
      items: [
        { key: 'douyinInstallPath', label: '安装路径', placeholder: '如: C:\\Users\\xxx\\AppData\\Local\\Douyin' },
        { key: 'douyinCacheDir', label: '缓存目录', placeholder: '自动发现后保存，或手动填写缓存目录' }
      ]
    },
    {
      id: 'netease', name: '网易云音乐', exeCandidates: ['cloudmusic.exe', 'CloudMusic.exe'],
      iconFallback: '<svg viewBox="0 0 24 24" fill="currentColor"><path d="M12 3v10.55A4 4 0 1 0 14 17V7h4V3h-6zM4 17a4 4 0 1 0 2 3.46A4 4 0 0 0 4 17z"/></svg>',
      items: [
        { key: 'neteaseMusicInstallPath', label: '安装路径', placeholder: '如: C:\\Program Files\\CloudMusic' },
        { key: 'neteaseCacheDir', label: '缓存目录', placeholder: '自动发现后保存，或手动填写缓存目录' }
      ]
    }
  ];

  const ALL_KEYS = GROUPS.flatMap(g => g.items.map(i => i.key));

  let pathConfig = {};
  // P0-1（F4a2-K02）：'ok' | 'degraded' 是后端 degraded 位的唯一前端落点，不再另造布尔镜像。
  // 旧实现只读 success/data，于是「配置损坏（已被隔离）」被折成「还没有配置」，
  // load 之后照排自动扫描，扫描结果逐个 paths.save —— 而 paths.save 写入的路径
  // 会被清理扫描原样采纳并永久删除（paths.rs 的 R1a-M01；后端分态口径见其 A1-M12）。
  // 真源被一次静默重建顶掉，所以这条状态位是永久删除链上的断点，不是展示层装饰。
  // 用户显式点「手动重建路径配置」即把它转回 ok：损坏文件在后端读取时就已 quarantine，
  // 此后写的是全新配置，不再需要额外第二个状态位表达「人工已确认」。
  let pathConfigState = 'ok';
  let icons = {};        // groupId -> dataUrl
  let isInitialized = false;
  let modal = null;      // { ctrl, backdrop, body, hint }

  function escapeAttr(s) { return window.ds.escAttr(s); }

  function getLabel(key) {
    for (const group of GROUPS) {
      const item = group.items.find(i => i.key === key);
      if (item) return `${group.name}${item.label}`;
    }
    return key;
  }

  function groupOf(key) {
    return GROUPS.find(g => g.items.some(i => i.key === key)) || null;
  }

  // ==================== 图标 ====================
  async function loadIcons() {
    if (!window.api?.paths) return;
    for (const group of GROUPS) {
      // 内置 base64 图标（抖音）：直接使用，跳过一切文件系统/IPC 依赖
      if (group.iconDataUrl) { icons[group.id] = group.iconDataUrl; continue; }
      // 固定图标路径（exe 图标不正确时的兜底方案）
      if (group.fixedIconPath && window.api.paths.fileIcon) {
        try {
          const resp = await window.api.paths.fileIcon(group.fixedIconPath);
          if (resp && resp.success && resp.dataUrl) { icons[group.id] = resp.dataUrl; continue; }
        } catch (e) { /* 固定图标不可用则继续尝试 exe 提取 */ }
      }
      const installPath = pathConfig[group.items[0].key] || '';
      if (!installPath || !window.api.paths.appIcon) continue;
      try {
        const resp = await window.api.paths.appIcon(installPath, group.exeCandidates);
        if (resp && resp.success && resp.dataUrl) icons[group.id] = resp.dataUrl;
      } catch (e) { /* 图标提取失败使用占位图标 */ }
    }
  }

  async function refreshGroupIcon(groupId) {
    const group = GROUPS.find(g => g.id === groupId);
    if (!group || !modal) return;
    // 内置 base64 图标直接设置
    if (group.iconDataUrl) { icons[groupId] = group.iconDataUrl; }
    else if (group.fixedIconPath && window.api?.paths?.fileIcon) {
      try {
        const resp = await window.api.paths.fileIcon(group.fixedIconPath);
        if (resp && resp.success && resp.dataUrl) { icons[groupId] = resp.dataUrl; }
      } catch (e) { /* 忽略 */ }
    }
    const img = modal.body.querySelector(`[data-group="${groupId}"] .pw-group-ico img`);
    const ico = modal.body.querySelector(`[data-group="${groupId}"] .pw-group-ico`);
    if (!ico) return;
    if (icons[groupId]) {
      if (img) img.src = icons[groupId];
      // 审查 v2-F14：与 `groupIconHtml` 取齐，dataUrl 也过 `escapeAttr`
      else ico.innerHTML = `<img src="${escapeAttr(icons[groupId])}" alt="${escapeAttr(group.name)}" />`;
    }
  }

  function groupIconHtml(group) {
    if (icons[group.id]) return `<img src="${escapeAttr(icons[group.id])}" alt="${escapeAttr(group.name)}" />`;
    return group.iconFallback;
  }

  // ==================== 弹窗渲染 ====================
  function renderBody() {
    if (!modal) return;
    // 损坏态用共享失败态件（window.errorState，A1-L07 已把「读取失败」与「确实为空」
    // 做成可分辨的同源结构件，本域不另造第三种）：不渲染可编辑项，就没有任何顺手的
    // 写回入口，唯一出口是用户显式重建。
    if (pathConfigState === 'degraded') {
      modal.body.innerHTML = window.errorState({
        title: '路径配置已损坏并被隔离',
        desc: '为避免误删，本次不会自动扫描，也不会写入任何路径。逐项确认后手动填写即可重建配置。',
        cta: { text: '手动重建路径配置', target: 'manualRebuild' },
      });
      modal.body.querySelector('[data-empty-cta="manualRebuild"]')?.addEventListener('click', () => {
        // 只把界面解锁成可手工编辑：不补数据、不排扫描，扫描留给用户自己再点一次。
        pathConfigState = 'ok';
        renderBody();
        updateFooter();
      });
      return;
    }
    modal.body.innerHTML = GROUPS.map(group => {
      const itemsHtml = group.items.map(item => {
        const value = pathConfig[item.key] || '';
        let hint = '', hintCls = '';
        if (!value) { hint = '未绑定，可点击「浏览」选择或手动填写'; hintCls = ''; }
        // F4a2-L02：删除 startsWith('!') 哨兵分支 —— 全仓现算无任何生产者写入 '!' 前缀
        // （唯一命中即原消费点本身），死分支会让读者误以为存在该约定；若将来要恢复，
        // 须先在写入侧定义约定并配门禁。
        return `
          <div class="pw-item" data-key="${escapeAttr(item.key)}">
            <span class="pw-item-label">${escapeAttr(item.label)}</span>
            <div class="pw-item-input">
              <input type="text" class="field-input pw-input" data-key="${escapeAttr(item.key)}"
                     value="${escapeAttr(value)}" placeholder="${escapeAttr(item.placeholder)}" spellcheck="false" />
              <div class="pw-hint ${hintCls}" data-hint="${escapeAttr(item.key)}">${escapeAttr(hint)}</div>
            </div>
            <button class="btn btn-secondary btn-small pw-browse" data-key="${escapeAttr(item.key)}" data-tip="浏览选择文件夹">浏览</button>
          </div>`;
      }).join('');
      return `
        <section class="pw-group" data-group="${escapeAttr(group.id)}">
          <div class="pw-group-head">
            <span class="pw-group-ico">${groupIconHtml(group)}</span>
            <span class="pw-group-title">${escapeAttr(group.name)}</span>
            <span class="pw-group-meta">${group.items.length} 项路径</span>
          </div>
          <div class="pw-items">${itemsHtml}</div>
        </section>`;
    }).join('');
    bindBodyEvents();
  }

  function bindBodyEvents() {
    if (!modal) return;
    modal.body.querySelectorAll('.pw-input').forEach(input => {
      const commit = () => savePath(input.dataset.key, input.value.trim());
      input.addEventListener('change', commit);
      input.addEventListener('blur', () => {
        if (input.value.trim() !== (pathConfig[input.dataset.key] || '')) commit();
      });
    });
    modal.body.querySelectorAll('.pw-browse').forEach(btn => {
      btn.addEventListener('click', () => browsePath(btn.dataset.key));
    });
  }

  function setHint(key, text, cls) {
    if (!modal) return;
    const el = modal.body.querySelector(`[data-hint="${key}"]`);
    if (!el) return;
    el.textContent = text || '';
    el.className = 'pw-hint' + (cls ? ' ' + cls : '');
  }

  // ==================== 数据读写 ====================
  async function savePath(key, value) {
    if (!window.api?.paths) return;
    try {
      const resp = await window.api.paths.save(key, value);
      if (resp && resp.success) {
        pathConfig[key] = value;
        if (!value) { setHint(key, '未绑定，可点击「浏览」选择或手动填写', ''); }
        else if (!resp.exists) { setHint(key, '路径不存在，请检查', 'warn'); window.app?.toast('warning', `${getLabel(key)} 路径不存在，请检查`); }
        else { setHint(key, '已保存', 'ok'); }
        const group = groupOf(key);
        if (group && group.items[0].key === key) {
          icons[group.id] = null;
          await refreshGroupIcon(group.id);
        }
      } else {
        // 审查 SET-1（2026-09-15）：原实现无失败分支 → 主进程拒绝（白名单未收录 / 落盘失败）
        // 时界面无任何反馈，用户误以为「已保存」。这里显式回滚提示，避免输入静默丢失。
        setHint(key, '保存失败，请重试', 'warn');
        window.app?.toast('error', `保存失败：${resp?.message || '路径配置无效'}`);
      }
    } catch (e) {
      window.app?.toast('error', '保存失败: ' + e.message);
    }
  }

  async function browsePath(key) {
    if (!window.api?.paths) return;
    try {
      const resp = await window.api.paths.browse(getLabel(key), pathConfig[key] || '');
      if (resp && resp.success && resp.path) {
        const input = modal?.body.querySelector(`.pw-input[data-key="${key}"]`);
        if (input) input.value = resp.path;
        await savePath(key, resp.path);
      }
    } catch (e) {
      window.app?.toast('error', '浏览失败: ' + e.message);
    }
  }

  async function autoScan(silent) {
    if (!window.api?.paths) return 0;
    // P0-1：degraded 下一个 paths.save 都不许发出去 —— 扫描会把损坏配置静默重建成
    // 「扫到的就是真的」，而该真源随后被清理扫描原样采纳并永久删除（paths.rs R1a-M01）。
    // 弹窗「重新扫描」按钮也走本入口，所以拒绝要给可见回执，不能静默返回 0。
    if (pathConfigState === 'degraded') {
      window.app?.toast('warning', '路径配置已损坏，请先手动重建配置后再扫描');
      return 0;
    }
    try {
      window.pathbindingAppearance.log('info', '开始自动扫描安装路径');
      const resp = await window.api.paths.scan();
      if (resp && resp.success && resp.data) {
        let found = 0;
        for (const item of ALL_KEYS) {
          const scanned = resp.data[item] || '';
          if (scanned && !pathConfig[item]) {
            pathConfig[item] = scanned;
            await window.api.paths.save(item, scanned);
            found++;
          }
        }
        if (resp.data.scannedAt) {
          // P3 顺手修（2026-10-09）：不再回写 scannedAt —— 后端 paths_scan 已把本次
          // 时间戳一并落盘（paths.rs 的 SET-5），这里再发 paths.save('scannedAt', …)
          // 恒被后端以「不是绝对路径」拒绝：Electron 时代遗留的冗余调用，
          // 每次启动在日志里留一条 WARN。页脚显示用的本地镜像同步保留。
          pathConfig.scannedAt = resp.data.scannedAt;
        }
        await loadIcons();
        renderBody();
        updateFooter();
        if (!silent) {
          if (found > 0) window.app?.toast('success', `安装路径扫描完成，已自动绑定 ${found} 项`);
          else window.app?.toast('info', '安装路径扫描完成，部分路径未识别，请手动填写');
        }
        return found;
      }
    } catch (e) {
      window.app?.toast('error', '路径扫描失败: ' + e.message);
    }
    return 0;
  }

  // 「扫过没有」的唯一判据：scannedAt 能被解析成有效时间。
  // 页脚文案与首次自动扫描共用它，避免两处各写一份 `new Date()` 口径。
  function parsedScannedAt(raw) {
    if (!raw) return null;
    const d = new Date(raw);
    return Number.isFinite(d.getTime()) ? d : null;
  }

  function updateFooter() {
    if (!modal) return;
    // 升级前落盘的 scannedAt 是 Rust 的 Debug 形态（`SystemTime { .. }`）—— `new Date()`
    // 对它返回**truthy 的 Invalid Date**，照字面拼进页脚就是「上次扫描：Invalid Date」。
    // 解析不出（getTime() 非有限值）一律按「未扫描」呈现；重新扫描会写入 ISO-8601
    // （见 commands/paths.rs），正常路径不受影响。
    const d = parsedScannedAt(pathConfig.scannedAt);
    const at = d ? d.toLocaleString('zh-CN') : '';
    if (pathConfigState === 'degraded') {
      // 损坏态不引导任何扫描动作：脚注若仍写「可点击重新扫描自动识别」，
      // 就与面板上的「本次不会自动扫描或写入」自相矛盾。
      modal.hint.textContent = '路径配置损坏，请逐项手动填写后保存';
      return;
    }
    modal.hint.textContent = at ? `上次扫描：${at}` : '尚未扫描，可点击「重新扫描」自动识别';
  }

  // ==================== 弹窗开关 ====================
  // v3.2.0 弹窗统一批次：骨架改由 modal.js 工厂生成（Esc/遮罩/× 关闭 + 焦点陷阱统一）
  function openModal() {
    closeModal();
    const ctrl = window.modal.create({
      id: 'pathBindingBackdrop',
      title: '安装路径绑定',
      backdropClass: 'path-binding-backdrop',
      modalClass: 'path-binding-modal',
      bodyClass: 'pw-body path-binding-body',
      bodyHtml: '<div class="pw-empty">正在加载路径配置…</div>',
      footerClass: 'pw-footer',
      footerHtml: `
          <span class="pw-last-scan" data-role="hint"></span>
          <span class="model-picker-spacer"></span>
          <button class="btn btn-secondary" data-role="scanBtn" type="button">重新扫描</button>
          <button class="btn btn-primary" data-role="doneBtn" type="button">完成</button>`
    });
    modal = {
      ctrl,
      backdrop: ctrl.backdrop,
      body: ctrl.body,
      hint: ctrl.backdrop.querySelector('[data-role="hint"]')
    };

    ctrl.backdrop.querySelector('[data-role="doneBtn"]').addEventListener('click', closeModal);
    ctrl.backdrop.querySelector('[data-role="scanBtn"]').addEventListener('click', async e => {
      const btn = e.currentTarget;
      btn.disabled = true;
      btn.textContent = '扫描中…';
      try { await autoScan(false); } finally { btn.disabled = false; btn.textContent = '重新扫描'; }
    });

    // 先渲染已保存配置，再后台补齐图标，避免等待图标造成白屏
    renderBody();
    updateFooter();
    loadIcons().then(() => renderBody());
  }

  function closeModal() {
    if (modal) { modal.ctrl.close(); modal = null; }
  }

  async function load() {
    if (!window.api?.paths) return;
    try {
      const resp = await window.api.paths.load();
      // 必须先读 degraded 再读 data（后端 commands/paths.rs 的 A1-M12 分态口径）：
      // 损坏被折成单态时 pathConfig 是隔离后的空对象，与首启 Absent 同形；若照旧
      // 只看 success+data，下面就会把它当首启排 autoScan，把猜测值逐键写回 paths.save
      // 真源（paths.rs R1a-M01：该真源被清理扫描原样采纳并永久删除）。
      if (resp && resp.degraded === true) {
        pathConfigState = 'degraded';
        pathConfig = {};
        window.pathbindingAppearance.log('warn', '路径配置已损坏并被隔离，已禁用自动扫描与自动写回');
        return;
      }
      if (resp && resp.success && resp.data) pathConfig = resp.data || {};
    } catch (e) {
      console.error('加载路径配置失败:', e);
    }

    // 首次启动自动扫描（仅在后台静默补全，不弹窗打扰）。
    // 判据只用后端回传的 `scannedAt`：`paths:scan` 每次都唯一产生时间戳并落盘，所以
    // 「这台机器上到底扫过没有」只有一个口径。原先另存一份 localStorage 标记是第二真源
    // ——清 WebView2 数据后标记丢了但 scannedAt 还在（对着已有绑定白扫一次），换机器则相反
    // （标记还在、扫描记录没了，从此再不补扫）。老配置里 scannedAt 若是升级前的 Debug 形态，
    // 由下方 normalizeScannedAt 归一后仍算「扫过」，不会退化成重新扫描。
    // 首启 Absent（degraded 未命中才会走到这里）仍照常自动扫描，本分支不得连带关闭。
    if (!parsedScannedAt(pathConfig.scannedAt)) {
      setTimeout(() => { autoScan(true); }, 1500);
    }
  }

  // ==================== 外观面装配（各面在各自文件里） ====================
  // 本入口只负责顺序与失败出口；背景图 / 材质 / 壁纸轮换的实现分别在
  // `pathbinding-background.js` / `pathbinding-material.js` /
  // `pathbinding-wallpaper.js`，外观偏好的镜像与真源口径在 `pathbinding-appearance.js`。

  // 背景图列表的两条失败出口。文案必须留在本文件：Rust 侧源码形状断言
  // （A1-L01/L02、A2-L02 用例）按本文件的字节判「读取失败不得与没有数据同形」，
  // 搬到背景图面会让 `cargo test` 判红，而改断言属 src-tauri/**（不在本批范围）。
  function bgListReadFailed(listEl, bodyEl) {
    listEl.style.display = 'block';
    bodyEl.innerHTML = '<div class="empty-state"><p>背景图列表读取失败</p></div>';
    window.app?.toast?.('error', '背景图列表读取失败');
  }
  function bgListLoadFailed(e) {
    window.app?.log?.('warn', '背景图列表加载失败: ' + ((e && e.message) || e));
    window.app?.toast?.('error', '背景图列表加载失败');
  }

  // 系统信息折叠（默认折叠，点击展开）。属设置页壳层，不归五个契约面里的任何一面。
  function initSystemInfoSection() {
    const sec = document.getElementById('systemInfoSection');
    const chevron = document.getElementById('systemInfoChevron');
    try {
      if (localStorage.getItem('trim-systeminfo-open') === '1' && sec) sec.classList.remove('collapsed');
    } catch (e) {}
    if (sec && !sec.classList.contains('collapsed') && chevron) chevron.textContent = '▴';
    document.getElementById('systemInfoToggle')?.addEventListener('click', () => {
      if (!sec) return;
      const open = sec.classList.toggle('collapsed') === false;
      if (chevron) chevron.textContent = open ? '▴' : '▾';
      try { localStorage.setItem('trim-systeminfo-open', open ? '1' : '0'); } catch (e) {}
    });
    // 阶段三：折叠区补齐 ARIA（不改视觉逻辑，ds.accordion 只同步 aria-expanded/hidden）
    if (sec) window.ds?.accordion?.enhance(document.getElementById('systemInfoToggle'), sec);
    // 键盘等价路径（A3-M03）：ds.accordion 不加 tabindex/keydown ⇒ 这个 div 头键盘走不到。
    // 与 `pathbinding-background.js` / `cleanup.js` 各留一份的原因写在那里：ds.js 属首屏
    // 12 脚本而预算已裁定不再上调；接线由 check-a11y「折叠头键盘接线」钉住。
    bindCollapseKeys(document.getElementById('systemInfoToggle'));
  }

  // 外观侧的总装配：各面只负责自己的控件与重放钩子，这里只定顺序。
  // 顺序约束：先做 skin→模糊迁移（背景图面 init 内），再做雾化度迁移，最后才允许重放；
  // 壁纸层模糊滑块的初值读在首帧重放之后（首帧时它还没登记出口，与拆分前一致）。
  function initAppearance() {
    const ap = window.pathbindingBackground.init();
    initSystemInfoSection();
    window.pathbindingMaterial.init();
    window.pathbindingWallpaper.init();
    window.pathbindingAppearance.applyAll(window.pathbindingAppearance.migrateBgOpacityToFog(ap));
    window.pathbindingBackground.initWallpaperBlur();
    // 后端优先合并 + 老键迁移：异步执行，不挡首帧（首帧按镜像值展示，回读有差异时重放）
    window.pathbindingAppearance.syncFromBackend()
      .catch((e) => window.pathbindingAppearance.log('warn', '外观偏好回读异常：' + ((e && e.message) || e)));
  }


  function init() {
    if (isInitialized) return;
    isInitialized = true;
    document.getElementById('btnRescanPaths')?.addEventListener('click', openModal);
    document.getElementById('btnOpenModels')?.addEventListener('click', () => {
      if (window.api?.modelsWindow?.open) {
        // 审查 v2-M22（v1 L13 未修）：开窗是浮动 Promise，失败时用户侧就是「点了没反应」。
        // 这里必须给可见回执；toast 走主窗 app，日志兜底留给 ds.js 的 rejection 网。
        window.api.modelsWindow.open().catch((e) => {
          window.app?.toast('error', '打开「大模型管理」窗口失败：' + ((e && e.message) || e));
        });
      } else {
        window.app?.toast('warning', '当前环境不支持打开大模型管理窗口');
      }
    });
    document.getElementById('btnOpenFonts')?.addEventListener('click', () => {
      if (window.fontmanager && typeof window.fontmanager.open === 'function') {
        window.fontmanager.open();
      } else {
        window.app?.toast('warning', '当前环境不支持打开字体选择窗口');
      }
    });
    setTimeout(load, 300);
    initAppearance();
  }

  window.pathbinding = {
    init, load, autoScan, openModal, getConfig: () => pathConfig, GROUPS,
    // 背景图列表的失败出口：实现必须住本文件（见上方注释），由背景图面调用。
    bgListReadFailed, bgListLoadFailed
  };
})();
